/*
 * A319319  Heinz numbers of integer partitions such that every distinct
 *          submultiset has a different GCD.
 * https://oeis.org/A319319
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th smallest integer m that is squarefree, whose
 *            prime indices satisfy that every non‑empty submultiset has a
 *            distinct greatest common divisor. The values are generated by
 *            testing each integer in increasing order
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* ------------------------------------------------------------ */
/* Prime sieve and lookup ------------------------------------- */
static bool *is_prime_sieve = NULL;      /* is p prime */
static uint32_t *prime_list = NULL;      /* primes in ascending order */
static uint32_t *prime_to_index = NULL;  /* 0 if not prime, else 1‑based index */
static size_t prime_count = 0;           /* number of primes */
static const uint32_t SIEVE_LIMIT = 5000000; /* should cover all needed primes */

static void build_primes(void)
{
    if (is_prime_sieve) return;           /* already built */

    is_prime_sieve = (bool *)malloc((SIEVE_LIMIT + 1) * sizeof(bool));
    if (!is_prime_sieve) exit(1);

    for (uint32_t i = 0; i <= SIEVE_LIMIT; ++i) is_prime_sieve[i] = true;
    is_prime_sieve[0] = is_prime_sieve[1] = false;

    for (uint32_t p = 2; (uint64_t)p * p <= SIEVE_LIMIT; ++p) {
        if (is_prime_sieve[p]) {
            for (uint64_t q = (uint64_t)p * p; q <= SIEVE_LIMIT; q += p)
                is_prime_sieve[(size_t)q] = false;
        }
    }

    /* count primes */
    for (uint32_t i = 2; i <= SIEVE_LIMIT; ++i)
        if (is_prime_sieve[i]) ++prime_count;

    prime_list = (uint32_t *)malloc(prime_count * sizeof(uint32_t));
    prime_to_index = (uint32_t *)calloc(SIEVE_LIMIT + 1, sizeof(uint32_t));
    if (!prime_list || !prime_to_index) exit(1);

    size_t idx = 0;
    for (uint32_t i = 2; i <= SIEVE_LIMIT; ++i) {
        if (is_prime_sieve[i]) {
            prime_list[idx] = i;
            prime_to_index[i] = (uint32_t)(idx + 1); /* 1‑based */
            ++idx;
        }
    }
}

/* ------------------------------------------------------------ */
/* GCD for uint32_t ------------------------------------------- */
static inline uint32_t gcd32(uint32_t a, uint32_t b)
{
    while (b != 0) {
        uint32_t t = b;
        b = a % b;
        a = t;
    }
    return a;
}

/* ------------------------------------------------------------ */
/* Check that all non‑empty subsets of the indices give distinct GCDs */
static bool indices_unique(const uint32_t *indices, size_t k,
                           uint32_t *seen, uint32_t test_id)
{
    /* No need to check for duplicate indices separately; the next
       loop will detect duplicates of GCD = index. */
    uint32_t curr_gcds[64];
    size_t curr_sz = 0;

    for (size_t i = 0; i < k; ++i) {
        uint32_t idx = indices[i];
        uint32_t new_gcds[64];
        size_t new_sz = 0;

        new_gcds[new_sz++] = idx;
        for (size_t j = 0; j < curr_sz; ++j) {
            uint32_t ng = gcd32(curr_gcds[j], idx);
            new_gcds[new_sz++] = ng;
        }

        /* Check duplicates inside new_gcds and with already seen GCDs */
        for (size_t a = 0; a < new_sz; ++a) {
            uint32_t val = new_gcds[a];
            /* duplicate within new_gcds */
            for (size_t b = a + 1; b < new_sz; ++b) {
                if (val == new_gcds[b]) return false;
            }
            if (seen[val] == test_id) return false;
        }

        /* Mark all new GCDs for this test */
        for (size_t a = 0; a < new_sz; ++a)
            seen[new_gcds[a]] = test_id;

        /* Append new GCDs to current list */
        for (size_t a = 0; a < new_sz; ++a)
            curr_gcds[curr_sz++] = new_gcds[a];
    }

    return true;
}

/* ------------------------------------------------------------ */
/* Sequence storage ------------------------------------------------ */
static seq_t *seq_vals = NULL;
static size_t seq_len = 0;
static size_t seq_cap = 0;
static idx_t current_max_value = 0;      /* last integer tested */

/* ------------------------------------------------------------ */
/* Ensure enough terms are precomputed -------------------------- */
static uint32_t *seen_gcds = NULL;       /* for uniqueness tests */
static uint32_t test_id = 1;             /* increments each test */

static void generate_sequence(idx_t n)
{
    if (seq_vals) {
        if (seq_len >= (size_t)n) return;
    } else {
        seq_cap = 64;
        seq_vals = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        if (!seq_vals) exit(1);
    }

    build_primes();

    if (!seen_gcds) {
        seen_gcds = (uint32_t *)calloc(prime_count + 1, sizeof(uint32_t));
        if (!seen_gcds) exit(1);
    }

    uint64_t candidate = current_max_value + 1;

    for ( ; seq_len < (size_t)n; ++candidate) {
        if (candidate == 1) {          /* empty partition */
            if (seq_len == seq_cap) {
                seq_cap *= 2;
                seq_vals = (seq_t *)realloc(seq_vals, seq_cap * sizeof(seq_t));
                if (!seq_vals) exit(1);
            }
            seq_vals[seq_len++] = (seq_t)1;
            continue;
        }

        uint64_t temp = candidate;
        uint32_t idxs[12];
        size_t ki = 0;
        bool squarefree = true;

        for (size_t pi = 0; pi < prime_count; ++pi) {
            uint32_t p = prime_list[pi];
            uint64_t pp = (uint64_t)p * p;
            if (pp > temp) break;
            if (temp % p == 0) {
                int exp = 0;
                while (temp % p == 0) {
                    temp /= p;
                    ++exp;
                    if (exp > 1) { squarefree = false; break; }
                }
                if (!squarefree) break;
                uint32_t idx = prime_to_index[p];
                if (idx == 0) { squarefree = false; break; } /* should not happen */
                idxs[ki++] = idx;
            }
        }
        if (!squarefree) continue;

        if (temp > 1) {          /* remaining prime factor */
            if (ki >= 12) continue; /* safety limit */
            uint32_t idx = prime_to_index[(uint32_t)temp];
            if (idx == 0) continue; /* prime > SIEVE_LIMIT, skip */
            idxs[ki++] = idx;
        }

        /* Check uniqueness property */
        if (indices_unique(idxs, ki, seen_gcds, test_id)) {
            if (seq_len == seq_cap) {
                seq_cap *= 2;
                seq_vals = (seq_t *)realloc(seq_vals, seq_cap * sizeof(seq_t));
                if (!seq_vals) exit(1);
            }
            seq_vals[seq_len++] = (seq_t)candidate;
        }
        ++test_id;
    }

    current_max_value = candidate - 1;
}

/* ------------------------------------------------------------ */
/* Public API --------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0; /* out of bounds; not used */
    generate_sequence(n);
    return seq_vals[n - 1];
}
